 const derivative=textbookDerivativeRoute(q);
 if(derivativeRouting.clarify.includes(q))return stop('needs_clarification','请明确要查的求导公式或具体函数。');
 if(!q||['函数','极限','连续','这个呢','它是多少','怎么做','它的范围是什么','输入是什么','它是什么','范围是什么'].includes(q)||/^(?:这个函数|该函数|它的|这个极限|这个表达式)/.test(q)&&!/=|sgn|sin|cos|tan|sqrt|ln|exp/.test(q))return stop('needs_clarification','请明确概念或具体函数及趋近过程。');
 if(/单调.*相等|单调.*严格/.test(q)&&!/数列|序列|函数/.test(q))return stop('needs_clarification','请区分函数与数列：本书这两处的单调记号约定不同。');
 const edition=q.match(/第([一二三四五六七八九十\d]+)版/),pm=q.match(/第(\d+)页|p(\d+)(?![a-z0-9])/),page=pm?Number(pm[1]||pm[2]):null;
 if(/下册|其他教材/.test(q)||edition&&!['五','5'].includes(edition[1]))return stop('not_covered','只核对第五版上册。');
 if(page!==null&&!units.some(u=>u.printedPages.includes(page)))return stop('not_covered','指定页不在当前选定来源，不代表全书没有。');
 if(/梯度下降|多元牛顿|全微分|微分方程|偏微分|多元微分|二阶微分|高阶微分|重积分|曲线积分|曲面积分|含参积分|勒贝格|主值的定义|级数|一致连续|海涅|原卷|试卷|复数|复变|傅里叶|有界(?:就|是否|能否|一定|必然).*连续|单调(?:函数)?.{0,6}(?:可以有|是否有|能否有).*间断/.test(q))return stop('not_covered','该问题需要当前选定资料以外的依据。');
